import type { Evidence } from '../../core/types.js';
import { defineCheck } from '../../core/check-builder.js';
import { extractToolDefinitions } from '../../mcp/tool-baseline.js';
import { levenshteinDistance } from '../../ioc/typosquat.js';

/**
 * MCP-025 — Cross-Server Tool-Name Collision / Shadowing.
 *
 * When two MCP servers expose tools with identical or near-identical names, the
 * client's tool routing becomes ambiguous and a malicious server can shadow a
 * trusted one — the model may invoke the attacker's `read_file` instead of the
 * legitimate one. Hou et al. (arXiv 2503.23278 §5.2.1, "tool name conflicts");
 * SlowMist checklist items 77/79.
 */

// Near-duplicate gating: names this short are too collision-prone to flag on
// edit distance alone (e.g. "ls" vs "cp"), so only exact matches count below it.
const MIN_LEN_FOR_NEAR_DUP = 4;
const NEAR_DUP_MAX_DISTANCE = 1;

interface ToolRef {
  server: string;
  tool: string;
}

export const mcp025 = defineCheck({
  id: 'MCP-025',
  name: 'Cross-Server Tool-Name Collision',
  category: 'mcp',
  severity: 'warning',
  description:
    'Detect identical or near-identical tool names exposed by different MCP servers, enabling tool shadowing',
  supportedAgents: ['mcp'],

  async run(ctx, h) {
    const sources = ctx.mcpServerSources ?? [];
    const evidence: Evidence[] = [];

    // Collect (server, tool) refs across every server with extractable tools.
    const refs: ToolRef[] = [];
    for (const source of sources) {
      const tools = source.tools ?? (source.sourceCode ? extractToolDefinitions(source.sourceCode) : []);
      for (const tool of tools) {
        refs.push({ server: source.serverName, tool: tool.name });
      }
    }

    // Exact collisions: same tool name owned by 2+ distinct servers.
    const byName = new Map<string, Set<string>>();
    for (const { server, tool } of refs) {
      if (!byName.has(tool)) byName.set(tool, new Set());
      byName.get(tool)!.add(server);
    }
    const reportedNames = new Set<string>();
    for (const [tool, servers] of byName) {
      if (servers.size >= 2) {
        reportedNames.add(tool);
        evidence.push({
          file: [...servers].join(', '),
          snippet: `Tool "${tool}"`,
          detail: `Tool name "${tool}" is exposed by ${servers.size} servers (${[...servers].join(', ')}) — tool routing is ambiguous and one server can shadow another`,
        });
      }
    }

    // Near-duplicates: distinct names within edit distance 1, owned by different
    // servers (one impersonating the other's tool). De-dup by sorted pair.
    const uniqueRefs = dedupeByServerTool(refs);
    const seenPairs = new Set<string>();
    for (let i = 0; i < uniqueRefs.length; i++) {
      for (let j = i + 1; j < uniqueRefs.length; j++) {
        const a = uniqueRefs[i];
        const b = uniqueRefs[j];
        if (a.server === b.server) continue;
        if (a.tool === b.tool) continue; // exact handled above
        if (reportedNames.has(a.tool) || reportedNames.has(b.tool)) continue;
        if (a.tool.length < MIN_LEN_FOR_NEAR_DUP || b.tool.length < MIN_LEN_FOR_NEAR_DUP) continue;
        if (Math.abs(a.tool.length - b.tool.length) > NEAR_DUP_MAX_DISTANCE) continue;
        if (levenshteinDistance(a.tool, b.tool) > NEAR_DUP_MAX_DISTANCE) continue;

        const pairKey = [`${a.server}:${a.tool}`, `${b.server}:${b.tool}`].sort().join('|');
        if (seenPairs.has(pairKey)) continue;
        seenPairs.add(pairKey);

        evidence.push({
          file: `${a.server}, ${b.server}`,
          snippet: `"${a.tool}" vs "${b.tool}"`,
          detail: `Tool "${a.tool}" (server "${a.server}") and "${b.tool}" (server "${b.server}") differ by one character — likely tool-shadowing / impersonation`,
        });
      }
    }

    return h.fromEvidence(evidence, {
      passed: 'No tool-name collisions across MCP servers',
      failed: (n) => `Found ${n} tool-name collision(s)/near-collision(s) across MCP servers — shadowing risk`,
      fixDescription:
        'Namespace tools per server (e.g. prefix with the server name) so identical tool names cannot collide, and remove servers exposing impersonating tool names',
    });
  },
});

function dedupeByServerTool(refs: ToolRef[]): ToolRef[] {
  const seen = new Set<string>();
  const out: ToolRef[] = [];
  for (const ref of refs) {
    const key = `${ref.server}�${ref.tool}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(ref);
  }
  return out;
}
